<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';security_headers();student_private_headers();$db=database();$student=student_account_current($db);if(!$student){header('Location: /aluno/login.php?next=%2Faluno%2Fcalibracao.php',true,303);exit;}$studentId=(int)$student['id'];try{student_tool_require($db,$studentId,'calibration');}catch(Throwable){http_response_code(403);exit('Ferramenta indisponível.');}$error='';$editId=(int)($_GET['editar']??$_POST['id']??0);$editing=$editId>0?student_calibration_for_student($db,$studentId,$editId):null;if($editId>0&&!$editing){http_response_code(404);exit('Referência não encontrada.');}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){if(!verify_csrf('student-calibration',$_POST['_csrf']??null))$error='Solicitação inválida.';else try{student_calibration_save($db,$studentId,$_POST);header('Location: /aluno/calibracao.php?saved=1',true,303);exit;}catch(Throwable $e){$error=$e->getMessage();}}
$rows=student_calibrations($db,$studentId);student_shell_start('Referências de calibração',null,$student);?>
<div class="student-appbar"><a class="student-back" href="/aluno/ferramentas.php">← Laboratório</a></div><p class="student-kicker">Referência pessoal</p><h1 class="student-title">Referências de calibração</h1><p class="student-lead">Registre o tempo de formação do branco para uma configuração que você efetivamente testou. É uma referência de consulta, não um cálculo automático do processo.</p><?php if(isset($_GET['saved'])):?><p class="ui-alert ui-alert-notice">Referência salva.</p><?php endif;?><?php if($error):?><p class="ui-alert ui-alert-error"><?=h($error)?></p><?php endif;?>
<section class="student-tool-workspace"><div class="student-section-heading"><div><p class="student-kicker"><?=$editing?'Edição':'Nova referência'?></p><h2 class="student-subtitle"><?=$editing?'Editar calibração':'Registrar calibração'?></h2></div></div><form method="post" class="student-form-grid"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-calibration'))?>"><?php if($editing):?><input type="hidden" name="id" value="<?=(int)$editing['id']?>"><?php endif;?><label class="form-field student-span-2">Nome<input name="label" required placeholder="Ex.: HR-U · Parodinal · 26 °C" value="<?=h((string)($editing['label']??''))?>"></label><label class="form-field">Filme<input name="film" value="<?=h((string)($editing['film']??''))?>"></label><label class="form-field">Revelador<input name="developer" value="<?=h((string)($editing['developer']??''))?>"></label><label class="form-field">Preparo / diluição<input name="preparation" value="<?=h((string)($editing['preparation']??''))?>"></label><label class="form-field">Temperatura<input name="temperature" value="<?=h((string)($editing['temperature']??''))?>"></label><label class="form-field">Pré-banho<input name="prebath" value="<?=h((string)($editing['prebath']??''))?>"></label><label class="form-field">Tempo do branco<input name="white_time" required value="<?=h((string)($editing['white_time']??''))?>"></label><details class="student-optional-fields student-span-2"<?=trim((string)($editing['notes']??''))!==''?' open':''?>><summary>Anotações</summary><label class="form-field"><textarea name="notes" rows="3"><?=h((string)($editing['notes']??''))?></textarea></label></details><div class="student-actions student-span-2"><button class="button button-primary" type="submit"><?=$editing?'Salvar alterações':'Salvar referência'?></button><?php if($editing):?><a class="button button-secondary" href="/aluno/calibracao.php">Cancelar</a><?php endif;?></div></form></section>
<section class="student-section"><div class="student-section-heading"><div><p class="student-kicker">Referências</p><h2 class="student-subtitle"><?=h(student_experience_count(count($rows),'calibração','calibrações'))?></h2></div></div><?php if(!$rows):?><div class="student-empty">Nenhuma calibração salva.</div><?php else:?><div class="student-test-list"><?php foreach($rows as $row):?><article class="student-simple-row"><div><h3><?=h((string)$row['label'])?></h3><p><?=h(implode(' · ',array_filter([(string)$row['film'],(string)$row['developer'],(string)$row['preparation'],(string)$row['temperature']])))?></p></div><div class="student-simple-row-actions"><strong><?=h((string)$row['white_time'])?></strong><a class="button button-secondary button-compact" href="/aluno/calibracao.php?editar=<?=(int)$row['id']?>">Editar</a></div></article><?php endforeach;?></div><?php endif;?></section><?php student_shell_end();